PRAGMA foreign_keys=ON;
CREATE TABLE sources(id TEXT PRIMARY KEY, url TEXT NOT NULL UNIQUE, kind TEXT NOT NULL DEFAULT 'reference');
CREATE TABLE admin_users(email TEXT PRIMARY KEY COLLATE NOCASE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE organizations(slug TEXT PRIMARY KEY,data TEXT NOT NULL CHECK(json_valid(data)),source_id TEXT NOT NULL REFERENCES sources(id),status TEXT NOT NULL CHECK(status IN('published','archived')),revision INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE services(slug TEXT PRIMARY KEY,data TEXT NOT NULL CHECK(json_valid(data)),source_id TEXT NOT NULL REFERENCES sources(id),organization_id TEXT REFERENCES organizations(slug),status TEXT NOT NULL CHECK(status IN('published','archived')),revision INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE events(slug TEXT PRIMARY KEY,data TEXT NOT NULL CHECK(json_valid(data)),source_id TEXT NOT NULL REFERENCES sources(id),organization_id TEXT REFERENCES organizations(slug),identity TEXT NOT NULL UNIQUE,ends_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('published','archived')),revision INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX events_calendar ON events(status,ends_at);
CREATE INDEX service_org ON services(organization_id,status);
CREATE TABLE submissions(id TEXT PRIMARY KEY,identity TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),sender TEXT,private_contact TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','expired')),created_at TEXT NOT NULL,reviewer TEXT,reviewed_at TEXT);
CREATE UNIQUE INDEX submission_open ON submissions(identity) WHERE status='pending';
CREATE TABLE scrape_runs(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '');
CREATE INDEX runs_recent ON scrape_runs(started_at DESC);
CREATE TABLE source_observations(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),url TEXT NOT NULL,digest TEXT NOT NULL,context TEXT NOT NULL,observed_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reviewer TEXT,reviewed_at TEXT);
CREATE INDEX observation_queue ON source_observations(status,observed_at);
CREATE TABLE change_history(id INTEGER PRIMARY KEY,entity TEXT NOT NULL,slug TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,actor TEXT NOT NULL,changed_at TEXT NOT NULL,UNIQUE(entity,slug,revision));
CREATE TABLE rate_limits(bucket TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TRIGGER audit_services_insert AFTER INSERT ON services BEGIN INSERT INTO change_history(entity,slug,data,status,revision,actor,changed_at) VALUES('services',NEW.slug,NEW.data,NEW.status,NEW.revision,NEW.actor,NEW.updated_at); END;
CREATE TRIGGER audit_services_update AFTER UPDATE ON services BEGIN INSERT INTO change_history(entity,slug,data,status,revision,actor,changed_at) VALUES('services',NEW.slug,NEW.data,NEW.status,NEW.revision,NEW.actor,NEW.updated_at); END;
CREATE TRIGGER audit_organizations_insert AFTER INSERT ON organizations BEGIN INSERT INTO change_history(entity,slug,data,status,revision,actor,changed_at) VALUES('organizations',NEW.slug,NEW.data,NEW.status,NEW.revision,NEW.actor,NEW.updated_at); END;
CREATE TRIGGER audit_organizations_update AFTER UPDATE ON organizations BEGIN INSERT INTO change_history(entity,slug,data,status,revision,actor,changed_at) VALUES('organizations',NEW.slug,NEW.data,NEW.status,NEW.revision,NEW.actor,NEW.updated_at); END;
CREATE TRIGGER audit_events_insert AFTER INSERT ON events BEGIN INSERT INTO change_history(entity,slug,data,status,revision,actor,changed_at) VALUES('events',NEW.slug,NEW.data,NEW.status,NEW.revision,NEW.actor,NEW.updated_at); END;
CREATE TRIGGER audit_events_update AFTER UPDATE ON events BEGIN INSERT INTO change_history(entity,slug,data,status,revision,actor,changed_at) VALUES('events',NEW.slug,NEW.data,NEW.status,NEW.revision,NEW.actor,NEW.updated_at); END;
